package br.com.sysanimais.api

import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.jupiter.api.*
import org.junit.jupiter.api.Assertions.*
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.http.MediaType
import org.springframework.jdbc.core.JdbcTemplate
import org.springframework.security.oauth2.jwt.*
import org.springframework.security.oauth2.jose.jws.MacAlgorithm
import org.springframework.test.context.TestPropertySource
import org.springframework.test.web.servlet.*
import org.springframework.transaction.annotation.Transactional
import java.time.Instant

@SpringBootTest @AutoConfigureMockMvc @Transactional
@TestPropertySource(properties=["spring.datasource.url=jdbc:h2:mem:financeiro;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","app.jwt-secret=0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"])
class FinanceiroApiTests @Autowired constructor(val mvc:MockMvc,val db:JdbcTemplate,val json:ObjectMapper,val jwt:JwtEncoder) {
 @jakarta.persistence.PersistenceContext lateinit var em:jakarta.persistence.EntityManager
 @BeforeEach fun fixtures(){
  db.update("INSERT INTO ong(id,nome,email) VALUES(701,'ONG A','a@finance.invalid'),(702,'ONG B','b@finance.invalid')")
  for((id,ong,perfil) in listOf(Triple(701,701,"administrador"),Triple(702,702,"administrador"),Triple(703,null,"usuario"),Triple(704,null,"usuario"),Triple(705,701,"voluntario"),Triple(706,701,"veterinario"),Triple(707,null,"admin_plataforma")))
   db.update("INSERT INTO usuario(id,ong_id,nome,email,senha_hash,perfil,ativo) VALUES(?,?,?,?,?,?,true)",id,ong,"Pessoa $id","u$id@finance.invalid","x",perfil)
 }
 private val donations="/api/ong/donations"
 private val finance="/api/ong/finance/movimentacoes"
 private fun auth(id:Int):String {val now=Instant.now();return "Bearer "+jwt.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),JwtClaimsSet.builder().subject(id.toString()).issuedAt(now).expiresAt(now.plusSeconds(3600)).build())).tokenValue}
 private fun post(path:String,body:String,user:Int=701)=mvc.post(path){header("Authorization",auth(user));contentType=MediaType.APPLICATION_JSON;content=body}
 private fun patch(path:String,user:Int=701,body:String?=null)=mvc.patch(path){header("Authorization",auth(user));if(body!=null){contentType=MediaType.APPLICATION_JSON;content=body}}
 private fun get(path:String,user:Int=701)=mvc.get(path){header("Authorization",auth(user))}
 private fun donation(value:String="25.50",user:Int=703,ong:Int=701):Long {val r=post("/api/donations","""{"ongId":$ong,"valor":"$value","mensagem":"Apoio"}""",user).andExpect{status{isCreated()};jsonPath("$.status"){value("PENDENTE")}}.andReturn();return json.readTree(r.response.contentAsString)["id"].asLong()}
 private fun movement(type:String="RECEITA",amount:String="25.50",user:Int=701):Long {val category=if(type=="RECEITA")"EVENTO"else"ALIMENTACAO";val r=post(finance,"""{"tipo":"$type","categoria":"$category","descricao":"Registro de teste","valor":"$amount"}""",user).andExpect{status{isCreated()};jsonPath("$.status"){value("PENDENTE")};jsonPath("$.origem.tipo"){value("MANUAL")}}.andReturn();return json.readTree(r.response.contentAsString)["id"].asLong()}
 @Test fun `doacao e confirmacao criam unica receita`(){val id=donation();get("/api/me/donations",703).andExpect{status{isOk()};jsonPath("$.totalElements"){value(1)};jsonPath("$.content[0].doador"){doesNotExist()}};patch("$donations/$id/confirmar").andExpect{status{isOk()};jsonPath("$.status"){value("CONFIRMADA")};jsonPath("$.confirmadoEm"){exists()}};patch("$donations/$id/confirmar").andExpect{status{isConflict()}};patch("$donations/$id/cancelar").andExpect{status{isConflict()}};get(finance).andExpect{jsonPath("$.totalElements"){value(1)};jsonPath("$.content[0].categoria"){value("DOACAO")};jsonPath("$.content[0].valor"){value("25.50")}};assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM movimentacao_financeira WHERE doacao_id=?",Int::class.java,id))}
 @Test fun `valores invalidos numeros e campos internos sao rejeitados`(){for(v in listOf("0","-1","1.234","10000000000.00","1e2","01.20","2,10"," ","0.00")){post("/api/donations","""{"ongId":701,"valor":"$v"}""",703).andExpect{status{isBadRequest()}}};post("/api/donations","""{"ongId":701,"valor":2.10}""",703).andExpect{status{isBadRequest()}};post(finance,"""{"tipo":"RECEITA","categoria":"DOACAO","descricao":"X","valor":"1.00"}""").andExpect{status{isBadRequest()}};post("/api/donations","""{"ongId":701,"valor":"1.00","status":"CONFIRMADA"}""",703).andExpect{status{isBadRequest()}};post(finance,"""{"tipo":"RECEITA","categoria":"EVENTO","descricao":"X","valor":"1.00","ongId":702}""").andExpect{status{isBadRequest()}}}
 @Test fun `limites monetarios e texto validados`(){donation("0.01");donation("9999999999.99");post(finance,"""{"tipo":"DESPESA","categoria":"EVENTO","descricao":"X","valor":"1.00"}""").andExpect{status{isBadRequest()}};post(finance,"""{"tipo":"RECEITA","categoria":"EVENTO","descricao":"   ","valor":"1.00"}""").andExpect{status{isBadRequest()}};post("/api/donations","""{"ongId":701,"valor":"1.00","mensagem":"${"x".repeat(2001)}"}""",703).andExpect{status{isBadRequest()}}}
 @Test fun `doacoes isoladas por usuario e ong`(){val id=donation();get("/api/me/donations",704).andExpect{jsonPath("$.totalElements"){value(0)}};get("/api/me/donations/$id",704).andExpect{status{isNotFound()}};patch("/api/me/donations/$id/cancelar",704).andExpect{status{isNotFound()}};get("$donations/$id",702).andExpect{status{isNotFound()}};patch("$donations/$id/confirmar",702).andExpect{status{isNotFound()}};get(donations,702).andExpect{jsonPath("$.totalElements"){value(0)}}}
 @Test fun `doacao cancelada preservada sem receita`(){val id=donation();patch("/api/me/donations/$id/cancelar",703).andExpect{status{isOk()};jsonPath("$.status"){value("CANCELADA")}};patch("$donations/$id/confirmar").andExpect{status{isConflict()}};get("/api/me/donations/$id",703).andExpect{jsonPath("$.historico.length()"){value(2)}};get(finance).andExpect{jsonPath("$.totalElements"){value(0)}};val other=donation();patch("$donations/$other/cancelar",body="""{"justificativa":"Desistência registrada"}""").andExpect{status{isOk()};jsonPath("$.justificativaCancelamento"){value("Desistência registrada")}}}
 @Test fun `receita so realizada apos recebimento`(){val id=movement(amount="100.01",user=705);get("/api/ong/finance/resumo").andExpect{jsonPath("$.receitasPendentes"){value("100.01")};jsonPath("$.saldoRealizado"){value("0.00")}};patch("$finance/$id/aprovar").andExpect{status{isConflict()}};patch("$finance/$id/confirmar-recebimento").andExpect{status{isOk()};jsonPath("$.status"){value("REALIZADA")}};patch("$finance/$id/confirmar-recebimento").andExpect{status{isConflict()}};patch("$finance/$id/cancelar").andExpect{status{isConflict()}};get("/api/ong/finance/resumo").andExpect{jsonPath("$.receitasRealizadas"){value("100.01")};jsonPath("$.receitasPendentes"){value("0.00")}}}
 @Test fun `aprovacao nao e pagamento`(){val id=movement("DESPESA","10.25",705);patch("$finance/$id/confirmar-pagamento").andExpect{status{isConflict()}};patch("$finance/$id/aprovar",body="""{"status":"REALIZADA"}""").andExpect{status{isBadRequest()}};patch("$finance/$id/aprovar").andExpect{status{isOk()};jsonPath("$.status"){value("APROVADA")}};get("/api/ong/finance/resumo").andExpect{jsonPath("$.despesasAprovadas"){value("10.25")};jsonPath("$.saldoRealizado"){value("0.00")}};patch("$finance/$id/aprovar").andExpect{status{isConflict()}};patch("$finance/$id/confirmar-pagamento").andExpect{status{isOk()};jsonPath("$.aprovadoEm"){exists()};jsonPath("$.confirmadoEm"){exists()}};get("/api/ong/finance/resumo").andExpect{jsonPath("$.despesasRealizadas"){value("10.25")};jsonPath("$.despesasAprovadas"){value("0.00")};jsonPath("$.saldoRealizado"){value("-10.25")}}}
 @Test fun `voluntario registra consulta mas nao decide`(){val id=movement("DESPESA",user=705);get(finance,705).andExpect{status{isOk()}};get("/api/ong/finance/resumo",705).andExpect{status{isOk()}};for(action in listOf("aprovar","confirmar-recebimento","confirmar-pagamento","cancelar"))patch("$finance/$id/$action",705).andExpect{status{isForbidden()}};val d=donation();get("$donations/$d",705).andExpect{status{isOk()}};for(a in listOf("confirmar","cancelar"))patch("$donations/$d/$a",705).andExpect{status{isForbidden()}}}
 @Test fun `perfis sem financeiro interno e anonimo bloqueados`(){mvc.get(finance).andExpect{status{isUnauthorized()}};for(user in listOf(703,706,707)){get(finance,user).andExpect{status{isForbidden()}};get("/api/ong/finance/resumo",user).andExpect{status{isForbidden()}};post(finance,"{}",user).andExpect{status{isForbidden()}};get(donations,user).andExpect{status{isForbidden()}}};for(user in listOf(701,705,706,707))post("/api/donations","{}",user).andExpect{status{isForbidden()}}}
 @Test fun `movimentos de outras ongs sao ocultos`(){val id=movement(user=702);for(a in listOf("aprovar","confirmar-recebimento","confirmar-pagamento","cancelar"))patch("$finance/$id/$a").andExpect{status{isNotFound()}};get("$finance/$id").andExpect{status{isNotFound()}};get(finance).andExpect{jsonPath("$.totalElements"){value(0)}}}
 @Test fun `cancelamento pendente e aprovado excluido dos totais`(){val a=movement(amount="500.00");val b=movement("DESPESA","100.00");patch("$finance/$b/aprovar").andExpect{status{isOk()}};for(id in listOf(a,b))patch("$finance/$id/cancelar",body="""{"justificativa":"Cancelado no teste"}""").andExpect{status{isOk()};jsonPath("$.status"){value("CANCELADA")};jsonPath("$.justificativaCancelamento"){value("Cancelado no teste")}};patch("$finance/$b/confirmar-pagamento").andExpect{status{isConflict()}};get("$finance/$b").andExpect{jsonPath("$.historico.length()"){value(3)}};get("/api/ong/finance/resumo").andExpect{jsonPath("$.receitasRealizadas"){value("0.00")};jsonPath("$.despesasAprovadas"){value("0.00")};jsonPath("$.saldoRealizado"){value("0.00")}}}
 @Test fun `origem automatica imutavel por endpoints manuais`(){val d=donation();patch("$donations/$d/confirmar").andExpect{status{isOk()}};val id=db.queryForObject("SELECT id FROM movimentacao_financeira WHERE doacao_id=?",Long::class.java,d)!!;for(a in listOf("aprovar","confirmar-recebimento","confirmar-pagamento","cancelar"))patch("$finance/$id/$a").andExpect{status{isConflict()}}}
 @Test fun `resumo decimal exato sem somar ongs pendencias e cancelados`(){for(v in listOf("0.10","0.20")){val id=movement(amount=v);patch("$finance/$id/confirmar-recebimento").andExpect{status{isOk()}}};val e=movement("DESPESA","0.07");patch("$finance/$e/aprovar");patch("$finance/$e/confirmar-pagamento");movement(amount="999.99");val other=movement(amount="1000.00",user=702);patch("$finance/$other/confirmar-recebimento",702);get("/api/ong/finance/resumo").andExpect{jsonPath("$.receitasRealizadas"){value("0.30")};jsonPath("$.despesasRealizadas"){value("0.07")};jsonPath("$.saldoRealizado"){value("0.23")};jsonPath("$.receitasPendentes"){value("999.99")}}}
 @Test fun `filtros paginacao e datas de evento do resumo`(){val r=movement(amount="10.05");val e=movement("DESPESA","3.02");patch("$finance/$r/confirmar-recebimento");patch("$finance/$e/aprovar");em.flush();em.clear();db.update("UPDATE movimentacao_financeira SET criado_em='2026-01-01 12:00:00',confirmado_em='2026-11-13 12:00:00' WHERE id=?",r);db.update("UPDATE movimentacao_financeira SET criado_em='2026-01-01 12:00:00',aprovado_em='2026-11-13 12:00:00' WHERE id=?",e);get("/api/ong/finance/resumo?de=2026-11-13&ate=2026-11-13").andExpect{jsonPath("$.receitasRealizadas"){value("10.05")};jsonPath("$.despesasAprovadas"){value("3.02")}};get("$finance?de=2026-11-13&ate=2026-11-13").andExpect{jsonPath("$.totalElements"){value(0)}};get("$finance?tipo=DESPESA&status=APROVADA&categoria=ALIMENTACAO&size=1").andExpect{jsonPath("$.totalElements"){value(1)}};get("$finance?size=1&page=1").andExpect{jsonPath("$.number"){value(1)};jsonPath("$.totalElements"){value(2)}};for(q in listOf("size=101","page=-1","de=2026-12-01&ate=2026-01-01","de=2026-02-30"))get("$finance?$q").andExpect{status{isBadRequest()}}}
 @Test fun `ong suspensa contas inativas e recursos ausentes`(){get("$finance/999999").andExpect{status{isNotFound()}};post("/api/donations","""{"ongId":999999,"valor":"1.00"}""",703).andExpect{status{isNotFound()}};db.update("UPDATE ong SET situacao='SUSPENSA' WHERE id=701");em.clear();get(finance).andExpect{status{isForbidden()}};post("/api/donations","""{"ongId":701,"valor":"1.00"}""",703).andExpect{status{isConflict()}};db.update("UPDATE ong SET situacao='ATIVA' WHERE id=701");db.update("UPDATE usuario SET ativo=false WHERE id=701");em.clear();get(finance).andExpect{status{isForbidden()}}}
 @Test fun `doacoes filtram periodo e pagina sem expor ator ao doador`(){val a=donation();donation();get("$donations?status=PENDENTE&size=1&page=1",705).andExpect{status{isOk()};jsonPath("$.number"){value(1)};jsonPath("$.totalElements"){value(2)};jsonPath("$.content[0].doador.id"){value(703)}};get("$donations?de=2100-01-01",705).andExpect{jsonPath("$.totalElements"){value(0)}};get("/api/me/donations/$a",703).andExpect{jsonPath("$.doador"){doesNotExist()};jsonPath("$.historico[0].ator"){doesNotExist()}}}
 @Test fun `resumo soma valores acima do limite de um lancamento sem overflow`(){repeat(2){val id=movement(amount="9999999999.99");patch("$finance/$id/confirmar-recebimento").andExpect{status{isOk()}}};get("/api/ong/finance/resumo").andExpect{jsonPath("$.receitasRealizadas"){value("19999999999.98")};jsonPath("$.saldoRealizado"){value("19999999999.98")}}}
 @Test fun `restricoes do banco protegem dinheiro e origem unica`(){val d=donation();assertThrows(org.springframework.dao.DataIntegrityViolationException::class.java){db.update("UPDATE doacao SET valor=-1 WHERE id=?",d)};patch("$donations/$d/confirmar").andExpect{status{isOk()}};assertThrows(org.springframework.dao.DataIntegrityViolationException::class.java){db.update("INSERT INTO movimentacao_financeira(ong_id,tipo,categoria,descricao,valor,status,doacao_id,registrado_por,confirmado_por,confirmado_em,criado_em,atualizado_em) SELECT ong_id,tipo,categoria,descricao,valor,status,doacao_id,registrado_por,confirmado_por,confirmado_em,criado_em,atualizado_em FROM movimentacao_financeira WHERE doacao_id=?",d)}}

}
